package techguns.gametest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import techguns.*;
import techguns.machines.*;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class MachineGameTests {
    private static ProcessingMachine machine(GameTestHelper h,MachineKind kind){h.setBlock(1,1,1,TGMachines.BLOCKS.get(kind).get());return (ProcessingMachine)h.getBlockEntity(new BlockPos(1,1,1));}
    private static void ammo(ProcessingMachine m,int count){m.inventory.setStackInSlot(0,new ItemStack(TGItems.INGOT_LEAD.get(),count));m.inventory.setStackInSlot(1,new ItemStack(Items.COPPER_INGOT,count*2));m.inventory.setStackInSlot(2,new ItemStack(Items.GUNPOWDER,count));}
    @GameTest(template="empty") public static void ammoPressProducesEverySourceBuildPlanWithExactInputsAndPower(GameTestHelper h){
        Item[] results={TGItems.PISTOL_ROUNDS.get(),TGItems.SHOTGUN_ROUNDS.get(),TGItems.RIFLE_ROUNDS.get(),TGItems.SNIPER_ROUNDS.get()};int[] counts={12,16,8,4};
        var m=machine(h,MachineKind.AMMO_PRESS);for(int plan=0;plan<4;plan++){m.plan=plan;ammo(m,1);m.setEnergy(500);m.tick();h.assertTrue(m.running()&&m.inventory.getStackInSlot(0).isEmpty(),"Starting reserves inputs exactly once");for(int i=0;i<100;i++)m.tick();var out=m.inventory.getStackInSlot(3);h.assertTrue(out.is(results[plan])&&out.getCount()==counts[plan]&&m.energy.getEnergyStored()==0,"Original ammo plan result after 100 ticks and 500 FE");m.inventory.setStackInSlot(3,ItemStack.EMPTY);}h.succeed();
    }
    @GameTest(template="empty") public static void powerLossAndRedstonePausePreserveInFlightOperation(GameTestHelper h){var m=machine(h,MachineKind.AMMO_PRESS);ammo(m,1);m.tick();m.tick();h.assertTrue(m.running()&&m.progress==0,"No power must pause the reserved operation");m.setEnergy(500);m.redstoneMode=1;m.tick();h.assertTrue(m.progress==0&&m.energy.getEnergyStored()==500,"High redstone mode pauses while signal is absent");m.redstoneMode=0;for(int i=0;i<37;i++)m.tick();h.assertTrue(m.progress==37&&m.energy.getEnergyStored()==315,"Only active work consumes energy");var tag=m.saveWithoutMetadata();var copy=new ProcessingMachine(m.getBlockPos(),m.getBlockState());copy.setLevel(h.getLevel());copy.load(tag);for(int i=37;i<100;i++)copy.tick();h.assertTrue(copy.inventory.getStackInSlot(3).getCount()==12&&copy.energy.getEnergyStored()==0&&!copy.running(),"Reload must resume the original output without consuming inputs again");h.succeed();}
    @GameTest(template="empty") public static void fullOutputBlocksStartAndDoesNotLoseFinishedOperation(GameTestHelper h){var m=machine(h,MachineKind.AMMO_PRESS);ammo(m,1);m.inventory.setStackInSlot(3,new ItemStack(Items.DIRT,64));m.tick();h.assertTrue(!m.running()&&m.inventory.getStackInSlot(0).getCount()==1,"An incompatible output must not consume ingredients");m.inventory.setStackInSlot(3,ItemStack.EMPTY);m.setEnergy(500);m.tick();m.inventory.setStackInSlot(3,new ItemStack(Items.DIRT,64));for(int i=0;i<102;i++)m.tick();h.assertTrue(m.running()&&m.progress==100&&m.pending().getCount()==12&&m.energy.getEnergyStored()==0,"Blocked completion retains output and stops consuming power");m.inventory.setStackInSlot(3,ItemStack.EMPTY);m.tick();h.assertTrue(!m.running()&&m.inventory.getStackInSlot(3).getCount()==12,"Freeing output completes the waiting transaction once");h.succeed();}
    @GameTest(template="empty") public static void stackUpgradeConservesIngredientsAndScalesPower(GameTestHelper h){var m=machine(h,MachineKind.AMMO_PRESS);ammo(m,3);m.inventory.setStackInSlot(4,new ItemStack(TGItems.MACHINE_UPGRADE_STACK.get(),2));m.setEnergy(1500);m.tick();h.assertTrue(m.pending().getCount()==36&&m.powerPerTick==15,"Two upgrades select a three-operation batch");for(int i=0;i<100;i++)m.tick();h.assertTrue(m.inventory.getStackInSlot(3).getCount()==36&&m.energy.getEnergyStored()==0,"Batch consumes three sets of ingredients and three times the energy");h.succeed();}
    @GameTest(template="empty") public static void metalPressAcceptsSwappedSourceIngredients(GameTestHelper h){var m=machine(h,MachineKind.METAL_PRESS);m.inventory.setStackInSlot(0,new ItemStack(Items.FLINT));m.inventory.setStackInSlot(1,TGItems.PLATE_IRON.get().getDefaultInstance());m.setEnergy(2000);m.tick();for(int i=0;i<100;i++)m.tick();h.assertTrue(m.inventory.getStackInSlot(2).is(TGItems.MECHANICAL_PARTS_IRON.get())&&m.energy.getEnergyStored()==0,"Swapped metal press ingredients retain the original output and operation duration");h.succeed();}
    @GameTest(template="empty") public static void blastFurnaceUsesFourIronAndOneCharcoalForFourSteel(GameTestHelper h){var m=machine(h,MachineKind.BLAST_FURNACE);m.inventory.setStackInSlot(0,new ItemStack(Items.IRON_INGOT,4));m.inventory.setStackInSlot(1,new ItemStack(Items.CHARCOAL));m.setEnergy(8000);m.tick();for(int i=0;i<800;i++)m.tick();h.assertTrue(m.inventory.getStackInSlot(2).is(TGItems.INGOT_STEEL.get())&&m.inventory.getStackInSlot(2).getCount()==4&&m.energy.getEnergyStored()==0,"Steel alloy consumes source amounts, 800 ticks and 8000 FE");h.succeed();}
    @GameTest(template="empty") public static void chargerConvertsOnlyOneEmptyBatteryPerOperation(GameTestHelper h){var m=machine(h,MachineKind.CHARGING_STATION);m.inventory.setStackInSlot(0,new ItemStack(TGItems.REDSTONE_BATTERY_EMPTY.get(),2));m.setEnergy(20000);m.tick();for(int i=0;i<25;i++)m.tick();h.assertTrue(m.inventory.getStackInSlot(1).is(TGItems.REDSTONE_BATTERY.get())&&m.inventory.getStackInSlot(0).getCount()==1&&m.energy.getEnergyStored()==0,"One battery conversion consumes 20000 FE without deleting the next empty battery");h.succeed();}
    @GameTest(template="empty") public static void automationCannotExtractIngredientsOrStealStoredEnergy(GameTestHelper h){var m=machine(h,MachineKind.AMMO_PRESS);ammo(m,1);var items=m.getCapability(ForgeCapabilities.ITEM_HANDLER).orElseThrow(IllegalStateException::new);h.assertTrue(items.extractItem(0,64,false).isEmpty(),"Automation may only extract output");h.assertTrue(items.insertItem(3,new ItemStack(Items.DIRT),false).getCount()==1,"Automation may not insert into output");var energy=m.getCapability(ForgeCapabilities.ENERGY).orElseThrow(IllegalStateException::new);energy.receiveEnergy(1234,false);h.assertTrue(!energy.canExtract()&&energy.extractEnergy(1000,false)==0&&energy.getEnergyStored()==1234,"The machine is an energy input, not an energy source");m.invalidateCaps();h.assertFalse(m.getCapability(ForgeCapabilities.ENERGY).isPresent(),"Removed machine must invalidate automation capabilities");m.reviveCaps();h.assertTrue(m.getCapability(ForgeCapabilities.ENERGY).isPresent(),"Revival reopens capabilities without losing inventory");h.succeed();}
}
